import * as OTPFieldPrimitive from "@kobalte/core/otp-field";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import type { ComponentProps, ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconMinusSign from "~icons/hugeicons/minus-sign";

import type { Component } from "solid-js";
import { merge, omit, Show } from "solid-js";

export const REGEXP_ONLY_DIGITS = "^\\d*$";
export const REGEXP_ONLY_CHARS = "^[a-zA-Z]*$";
export const REGEXP_ONLY_DIGITS_AND_CHARS = "^[a-zA-Z0-9]*$";

type InputOTPProps<T extends ValidComponent = "div"> =
  & OTPFieldPrimitive.OTPFieldRootProps<T>
  & { class?: string | undefined };

const InputOTP = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, InputOTPProps<T>>,
) => {
  const local = props as InputOTPProps;
  const rest = omit(local, "class");
  return (
    <OTPFieldPrimitive.Root
      class={cn(
        "gap-2 flex items-center has-disabled:opacity-50",
        local.class,
      )}
      {...rest}
    />
  );
};

type InputOTPInputProps<T extends ValidComponent = "input"> =
  & OTPFieldPrimitive.OTPFieldInputProps<T>
  & { class?: string | undefined };

const InputOTPInput = <T extends ValidComponent = "input">(
  rawProps: PolymorphicProps<T, InputOTPInputProps<T>>,
) => {
  const props = merge({ pattern: null }, rawProps as InputOTPInputProps);
  const rest = omit(props, "class", "onFocus");
  const onFocus: InputOTPInputProps["onFocus"] = (event) => {
    const handler = props.onFocus;
    if (typeof handler === "function") handler(event);
    else if (handler) handler[0](handler[1], event);
    requestAnimationFrame(() =>
      document.dispatchEvent(new Event("selectionchange"))
    );
  };
  return (
    <OTPFieldPrimitive.Input
      onFocus={onFocus}
      data-slot="input-otp"
      class={cn(
        "z-20 disabled:cursor-not-allowed",
        props.class,
      )}
      {...rest}
    />
  );
};

const InputOTPGroup: Component<ComponentProps<"div">> = (props) => {
  const rest = omit(props, "class");
  return (
    <div
      data-slot="input-otp-group"
      class={cn(
        "has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive rounded-4xl has-aria-invalid:ring-[3px] flex items-center",
        props.class,
      )}
      {...rest}
    />
  );
};

const InputOTPSlot: Component<ComponentProps<"div"> & { index: number }> = (
  props,
) => {
  const rest = omit(props, "class", "index");
  const context = OTPFieldPrimitive.useOTPFieldContext();
  const char = () => context.value()[props.index];
  const isActive = () => context.activeSlots().includes(props.index);
  const showFakeCaret = () =>
    context.value().length === props.index && context.isInserting();

  return (
    <div
      data-slot="input-otp-slot"
      data-active={isActive() ? "true" : undefined}
      class={cn(
        "bg-input/30 border-input data-[active=true]:border-ring data-[active=true]:ring-ring/50 data-[active=true]:aria-invalid:ring-destructive/20 dark:data-[active=true]:aria-invalid:ring-destructive/40 aria-invalid:border-destructive data-[active=true]:aria-invalid:border-destructive size-9 border-y border-r text-sm transition-all outline-none first:rounded-l-4xl first:border-l last:rounded-r-4xl data-[active=true]:ring-[3px] relative flex items-center justify-center data-[active=true]:z-10",
        props.class,
      )}
      {...rest}
    >
      {char()}
      <Show when={showFakeCaret()}>
        <div class="pointer-events-none absolute inset-0 flex items-center justify-center">
          <div class="animate-caret-blink bg-foreground h-4 w-px duration-1000" />
        </div>
      </Show>
    </div>
  );
};

const InputOTPSeparator: Component<ComponentProps<"div">> = (props) => {
  const rest = omit(props, "class");
  return (
    <div
      data-slot="input-otp-separator"
      class={cn(
        "[&_svg:not([class*='size-'])]:size-4 flex items-center",
        props.class,
      )}
      role="separator"
      {...rest}
    >
      <IconMinusSign
      />
    </div>
  );
};

export {
  InputOTP,
  InputOTPGroup,
  InputOTPInput,
  InputOTPSeparator,
  InputOTPSlot,
};
